        return new Source("{% extends 'base.html.twig' %}

{% block title %}Modifier la Réclamation{% endblock %}

{% block body %}
    <div class=\"container mt-4\">
        <h1>Modifier la Réclamation</h1>

        {{ form_start(form, {'attr': {'class': 'needs-validation'}}) }}
            <div class=\"mb-3\">
                {{ form_label(form.nom) }}
                {{ form_widget(form.nom) }}
                {{ form_errors(form.nom) }}
            </div>

            <div class=\"mb-3\">
                {{ form_label(form.email) }}
                {{ form_widget(form.email) }}
                {{ form_errors(form.email) }}
            </div>

            <div class=\"mb-3\">
                {{ form_label(form.message) }}
                {{ form_widget(form.message) }}
                {{ form_errors(form.message) }}
            </div>

            <button class=\"btn btn-primary\">{{ button_label|default('Enregistrer') }}</button>
            <a href=\"{{ path('app_reclamation_index') }}\" class=\"btn btn-secondary\">Retour à la liste</a>

            {{ form_end(form) }}

        <form method=\"post\" action=\"{{ path('app_reclamation_delete', {'id': reclamation.id}) }}\" onsubmit=\"return confirm('Êtes-vous sûr de vouloir supprimer cette réclamation?');\" class=\"mt-3\">
            <input type=\"hidden\" name=\"_token\" value=\"{{ csrf_token('delete' ~ reclamation.id) }}\">
            <button class=\"btn btn-danger\">Supprimer</button>
        </form>
    </div>
{% endblock %}
